def read_lines(path):
    lines = []
    with open(path, "r", encoding="utf-8") as file:
        for line in file:
            text = line.rstrip("\r\n")
            lines.append(text)
    return lines

def is_palindrome(text):
    if text == "":
        return False

    reversed_text = text[::-1]
    return text == reversed_text

lines = read_lines("data.txt")
palindromes = []
for text in lines:
    if is_palindrome(text):
        palindromes.append(text)

print(palindromes)
